INSERT INTO inmueble_operativo(id_propietario,id_ciudad,titulo,descripcion,direccion_detallada,tipo,capacidad,tarifa_noche,moneda,estado) SELECT u.id_usuario,c.id_ciudad,'Apartamento mediterráneo en Cartagena','Alojamiento de prueba para distinguir ciudades homónimas. Fotografía ilustrativa.','Centro de Cartagena, dirección de demostración','APARTAMENTO',3,95,'EUR','PUBLICADO' FROM usuario u CROSS JOIN ciudad c JOIN division_administrativa d USING(id_division) JOIN pais p ON p.id_pais=d.id_pais WHERE u.correo_normalizado='propietario1@renta.test' AND c.codigo_oficial='30016' AND p.codigo_iso2='ES' AND NOT EXISTS(SELECT 1 FROM inmueble_operativo i WHERE i.id_ciudad=c.id_ciudad AND i.titulo='Apartamento mediterráneo en Cartagena');
INSERT INTO banco(nombre,id_pais) SELECT 'Banco demo '||nombre,id_pais FROM pais ON CONFLICT DO NOTHING;
